from random import randint

def solve_e(m, c, n, A):
	M = 998244353

	def multiply(v):
		r = [0] * n
		for i in range(n):
			for j in range(n):
				r[i] += A[i][j] * v[j]
				r[i] %= M
		return r
	v = [randint(0, M - 1) for _ in range(n)]
	tmp = [0 for _ in range(n)]
	for i in range(m):
		for j in range(n):
			tmp[j] += c[i] * v[j]
			tmp[j] %= M
		v = multiply(v)
	for j in range(n):
		if tmp[j] != 0:
			return 'NO'
	return 'YES'
